// genFailWriter lets limit bytes through, then fails.
type genFailWriter struct {
	limit   int
	written int
}

func (w *genFailWriter) Write(p []byte) (int, error) {
	if w.written >= w.limit {
		return 0, errors.New("sweep: writer failed")
	}
	if allow := w.limit - w.written; len(p) > allow {
		w.written = w.limit
		return allow, errors.New("sweep: writer failed")
	}
	w.written += len(p)
	return len(p), nil
}

